        "contentDigest": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "digest",
            "algorithm",
            "scope",
            "scopeId"
          ],
          "properties": {
            "digest": {
              "type": "string",
              "minLength": 32,
              "maxLength": 256
            },
            "algorithm": {
              "enum": [
                "sha256",
                "blake3",
                "hmac-sha256",
                "hmac-blake3"
              ]
            },
            "scope": {
              "enum": [
                "global_public",
                "user_local",
                "workspace",
                "repo",
                "provider",
                "managed_policy_scope"
              ]
            },
            "scopeId": {
              "$ref": "#/$defs/id"
            },
            "keyRef": {
              "$ref": "#/$defs/id"
            },
            "portableExportDigest": {
              "type": "string",
              "minLength": 32,
              "maxLength": 256
            }
          },
          "allOf": [
            {
              "if": {
                "properties": {
                  "scope": {
                    "const": "global_public"
                  }
                },
                "required": [
                  "scope"
                ]
              },
              "then": {
                "properties": {
                  "algorithm": {
                    "enum": [
                      "sha256",
                      "blake3"
                    ]
                  }
                },
                "not": {
                  "required": [
                    "keyRef"
                  ]
                }
              },
              "else": {
                "required": [
                  "keyRef"
                ],
                "properties": {
                  "algorithm": {
                    "enum": [
                      "hmac-sha256",
                      "hmac-blake3"
                    ]
                  }
                }
              }
            }
          ]
        },
